import extractText from 'flarum/common/utils/extractText';
import Stream from 'flarum/common/utils/Stream';
import FormDropdown from './FormDropdown';
export default class InsertImageDropdown extends FormDropdown {
  oninit(vnode) {
    super.oninit(vnode);
    this.src = Stream('');
    this.title = Stream('');
  }
  fields() {
    const items = super.fields();
    items.add('src', m("div", {
      className: "Form-group"
    }, m("input", {
      className: "FormControl",
      name: "src",
      type: "url",
      placeholder: extractText(app.translator.trans('fof-rich-text.lib.composer.insert_image.src_placeholder')),
      bidi: this.src,
      required: true
    })), 10);
    items.add('title', m("div", {
      className: "Form-group"
    }, m("input", {
      className: "FormControl",
      name: "title",
      placeholder: extractText(app.translator.trans('fof-rich-text.lib.composer.insert_image.title_placeholder')),
      bidi: this.title
    })), 10);
    return items;
  }
  insert(e) {
    this.attrs.editor.chain().focus().setImage({
      src: this.src(),
      title: this.title()
    }).run();
    this.src('');
    this.title('');
  }
}
flarum.reg.add('fof-rich-text', 'common/components/InsertImageDropdown', InsertImageDropdown);