import Button from 'flarum/common/components/Button';
import extractText from 'flarum/common/utils/extractText';
import Stream from 'flarum/common/utils/Stream';
import FormDropdown from './FormDropdown';
export default class InsertLinkDropdown extends FormDropdown {
  oninit(vnode) {
    super.oninit(vnode);
    this.text = Stream('');
    this.href = Stream('');
    this.title = Stream('');
    this.active = false;
    this.selectionEmpty = true;
    this.isOpen = false;
  }
  oncreate(vnode) {
    super.oncreate(vnode);
    this.$().on('shown.bs.dropdown', () => {
      this.isOpen = true;
    });
    this.$().on('hidden.bs.dropdown', () => {
      this.isOpen = false;
    });
  }
  onupdate(vnode) {
    super.onupdate(vnode);
    if (this.isOpen) return;
    const editor = this.attrs.editor;
    if (!editor) return;
    this.active = editor.isActive('link');
    this.$('.Dropdown-toggle').toggleClass('active', this.active);
    const attrs = editor.getAttributes('link');
    this.href(attrs.href || '');
    this.title(attrs.title || '');
    this.selectionEmpty = editor.state.selection.empty;
  }
  fields() {
    const items = super.fields();
    if (this.selectionEmpty && !this.active) {
      items.add('text', m("div", {
        className: "Form-group"
      }, m("input", {
        className: "FormControl",
        name: "text",
        placeholder: extractText(app.translator.trans('fof-rich-text.lib.composer.insert_link.text_placeholder')),
        bidi: this.text,
        required: true
      })), 10);
    }
    items.add('href', m("div", {
      className: "Form-group"
    }, m("input", {
      className: "FormControl",
      name: "href",
      type: "url",
      placeholder: extractText(app.translator.trans('fof-rich-text.lib.composer.insert_link.href_placeholder')),
      bidi: this.href,
      required: true
    })), 10);
    items.add('title', m("div", {
      className: "Form-group"
    }, m("input", {
      className: "FormControl",
      name: "title",
      placeholder: extractText(app.translator.trans('fof-rich-text.lib.composer.insert_link.title_placeholder')),
      bidi: this.title
    })), 10);
    if (this.active) {
      items.add('remove', m(Button, {
        onclick: this.remove.bind(this),
        className: "Button Button--danger"
      }, app.translator.trans('fof-rich-text.lib.composer.insert_link.remove_button')), -10);
    }
    return items;
  }
  insert(e) {
    const editor = this.attrs.editor;
    const linkAttrs = {
      href: this.href(),
      title: this.title()
    };
    if (this.selectionEmpty && !this.active) {
      editor.chain().focus().insertContent({
        type: 'text',
        text: this.text(),
        marks: [{
          type: 'link',
          attrs: linkAttrs
        }]
      }).unsetMark('link').insertContent(' ').run();
    } else {
      editor.chain().focus().setLink(linkAttrs).run();
    }

    // Reset streams after insert
    this.text('');
    this.href('');
    this.title('');
  }
  remove(e) {
    $('body').trigger('click');
    this.attrs.editor.chain().focus().unsetLink().run();
    app.composer.editor.focus();
  }
}
flarum.reg.add('fof-rich-text', 'common/components/InsertLinkDropdown', InsertLinkDropdown);