import Button from 'flarum/common/components/Button';
import Dropdown from 'flarum/common/components/Dropdown';
import Icon from 'flarum/common/components/Icon';
import Tooltip from 'flarum/common/components/Tooltip';
import ItemList from 'flarum/common/utils/ItemList';
import SafariModalHack from './SafariModalHack';
export default class FormDropdown extends Dropdown {
  static initAttrs(attrs) {
    attrs.buttonClassName = 'Button Button--icon Button--link Button--menuDropdown';
  }
  oninit(vnode) {
    super.oninit(vnode);
    this.state = this.attrs.state;
  }
  oncreate(vnode) {
    super.oncreate(vnode);
    this.$().on('click', e => {
      if ($('.App').is('.mobile-safari')) {
        // Mobile Safari doesn't support fixed items
        // So, we wrap them in a modal.
        app.modal.show(SafariModalHack, {
          title: this.attrs.tooltip,
          vnodeContent: this.fields().toArray(),
          onsubmit: this.onsubmit.bind(this)
        });
        e.stopPropagation();
      }
    });
    this.$().on('shown.bs.dropdown', () => {
      this.$('.Dropdown-menu').find('input, select, textarea').first().focus().select();
    });
  }
  getButton(children) {
    return m("button", Object.assign({
      type: "button",
      className: 'Dropdown-toggle ' + this.attrs.buttonClassName,
      "aria-haspopup": "menu",
      "data-toggle": "dropdown",
      onclick: this.attrs.onclick
    }, this.attrs.buttonAttrs), this.getButtonContent(children));
  }
  getButtonContent(children) {
    return m(Tooltip, {
      text: this.attrs.tooltip
    }, m("span", null, m(Icon, {
      name: this.attrs.icon,
      className: "Button-icon"
    })));
  }
  getMenu(items) {
    return m("ul", {
      className: 'Dropdown-menu dropdown-menu FormDropdown'
    }, m("form", {
      className: "Form",
      onsubmit: this.onsubmit.bind(this)
    }, this.fields().toArray()));
  }
  fields() {
    const items = new ItemList();
    items.add('insert', m(Button, {
      type: "submit",
      className: "Button Button--primary"
    }, app.translator.trans('fof-rich-text.lib.composer.insert_button')));
    return items;
  }
  onsubmit(e) {
    // Here for the safari workaround
    app.modal.close();
    e.preventDefault();
    $('body').trigger('click');
    this.insert(e);
    app.composer.editor.focus();
  }
  insert(e) {}
}
flarum.reg.add('fof-rich-text', 'common/components/FormDropdown', FormDropdown);